# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">MUHACİRLERİN HZ. PEYGAMBER\'E (SAV) BAĞLILIĞI VE SADAKATİ (PH.7.2.2)</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Muhacir Kimdir? (622 Medine Hicreti)</text>\n  <text x="40" y="98" font-size="11" fill="#334155">• Allah (cc) ve Resulü\'nün rızasını kazanmak için</text>\n  <text x="40" y="118" font-size="11" fill="#334155">  yurdunu, evini ve malını bırakıp hicret eden sahabi</text>\n  <text x="40" y="142" font-size="11" fill="#334155">• İlk Hicret: Habeşistan (615) | Büyük Hicret: Medine (622)</text>\n  <text x="40" y="166" font-size="11" fill="#334155">• Boykot Yılları (616-619): Şi\'b-i Ebû Tâlib\'de sabır</text>\n  <text x="40" y="190" font-size="11" fill="#334155">• Akabe Biatları (620-622): Medine\'ye hicret zemini</text>\n  <text x="182" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">Haşr Suresi 8. Ayette Övülen Sadık Müminler</text>\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Sadakat ve İtimat Kavramları</text>\n  <text x="375" y="98" font-size="11" fill="#334155">• Sadakat: Hz. Peygamber\'e içten ve sarsılmaz bağlılık</text>\n  <text x="375" y="120" font-size="11" fill="#334155">• İtimat: Peygamberimizin her sözüne tam güven</text>\n  <text x="375" y="142" font-size="11" fill="#334155">• Sıddık: Doğruluğu tereddütsüz tasdik eden (Hz. Ebu Bekir)</text>\n  <text x="375" y="164" font-size="11" fill="#334155">• "Anam babam sana feda olsun yâ Resulallah!" hitabı</text>\n  <text x="375" y="186" font-size="11" fill="#334155">• Zorlukta ve kolaylıkta Sünnet-i Seniyye\'ye ittiba</text>\n  <text x="517" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">İman, Sevgi ve Fedakârlık Kardeşliği</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">HİCRET YOLUNDA ÖRNEK FEDAKÂRLIK TABLOLARI</text>\n  <rect x="20" y="48" width="210" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="125" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#a16207">1. Hz. Ebu Bekir (es-Sıddık)</text>\n  <text x="34" y="98" font-size="11" fill="#334155">• Hicret yol arkadaşı (Sevr Mağarası)</text>\n  <text x="34" y="120" font-size="11" fill="#334155">• Tevbe 40: "Üzülme, Allah bizimle!"</text>\n  <text x="34" y="142" font-size="11" fill="#334155">• Mazlum köleleri alıp azat etmesi</text>\n  <text x="34" y="164" font-size="11" fill="#334155">• Malını ve canını İslam\'a adaması</text>\n  <text x="125" y="216" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#92400e">Mağaradaki İki Kişinin İkincisi</text>\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="350" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#1d4ed8">2. Hz. Ali\'nin (ra) Cesaret ve Vefası</text>\n  <text x="259" y="98" font-size="11" fill="#334155">• Hicret gecesi suikast tehlikesine</text>\n  <text x="259" y="118" font-size="11" fill="#334155">  rağmen Peygamberimizin yatağında</text>\n  <text x="259" y="138" font-size="11" fill="#334155">  hiç çekinmeden yatması</text>\n  <text x="259" y="162" font-size="11" fill="#334155">• Mekke\'deki emanetleri sahiplerine</text>\n  <text x="259" y="182" font-size="11" fill="#334155">  teslim edip Medine\'ye yürümesi</text>\n  <text x="350" y="216" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1e40af">Emanet ve Cesaret Timsali</text>\n  <rect x="470" y="48" width="210" height="190" rx="8" fill="#fdf2f8" stroke="#ec4899"/>\n  <text x="575" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#be185d">3. Suheyb-i Rûmî ve Mus\'ab (ra)</text>\n  <text x="484" y="98" font-size="11" fill="#334155">• Suheyb-i Rûmî: Bütün servetini</text>\n  <text x="484" y="118" font-size="11" fill="#334155">  müşriklere bırakıp hicret etmesi</text>\n  <text x="484" y="140" font-size="11" fill="#334155">  ("Alışverişin kârlı oldu ey Ebû Yahya!")</text>\n  <text x="484" y="164" font-size="11" fill="#334155">• Mus\'ab bin Umeyr: Zenginliği terk</text>\n  <text x="484" y="184" font-size="11" fill="#334155">  edip İslam\'ın ilk öğretmeni olması</text>\n  <text x="575" y="216" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#9d174d">Bakara 207 İle Övülen Fedakârlık</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">MUHACİRLERİN DİLİNDEN PEYGAMBERİMİZ (SAV)</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Sahabilerin Dilinden Üstün Vasıfları</text>\n  <text x="40" y="98" font-size="11" fill="#334155">• Hz. Hatice (ra): "Sen akrabayı gözetir, doğru söylersin."</text>\n  <text x="40" y="120" font-size="11" fill="#334155">• Hz. Ali (ra): "O, insanların en cömerdi ve en cesuruydu."</text>\n  <text x="40" y="142" font-size="11" fill="#334155">• Hz. Âişe (ra): "Onun ahlakı Kur\'an ahlakıydı."</text>\n  <text x="40" y="164" font-size="11" fill="#334155">• Urve bin Mes\'ûd: "Hiçbir hükümdarda böyle sevgi görmedim."</text>\n  <text x="40" y="186" font-size="11" fill="#334155">• Hubeyb bin Adî: "Diken batmasına bile razı olmam!"</text>\n  <text x="182" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Korku Değil, Gönülden Sevgi ve Hürmet</text>\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Ensar - Muhacir Kardeşliği (Muâhât)</text>\n  <text x="375" y="98" font-size="11" fill="#334155">• Muhacir: Mekke\'den Medine\'ye göç eden müminler</text>\n  <text x="375" y="120" font-size="11" fill="#334155">• Ensar: Medineli "yardım eden" ev sahibi müminler</text>\n  <text x="375" y="142" font-size="11" fill="#334155">• Muâhât: Peygamberimizin ilan ettiği kardeşlik akdi</text>\n  <text x="375" y="164" font-size="11" fill="#334155">• Abdurrahman bin Avf ile Sa\'d bin Rebî (ra) örneği</text>\n  <text x="375" y="186" font-size="11" fill="#334155">• Îsâr Ahlakı: Kardeşini kendi nefsine tercih etmek</text>\n  <text x="517" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">Medine İslam Toplumunun Temeli</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
